"""
Script para salvar o logo da Caixa corretamente
"""
import base64
import os

# Logo da Caixa em base64 (da imagem PNG fornecida)
logo_base64 = """

"""

# Diretório de destino
logo_dir = os.path.join('boletos', 'static', 'boletos', 'img')
logo_path = os.path.join(logo_dir, 'logo_caixa.png')

# Cria o diretório se não existir
os.makedirs(logo_dir, exist_ok=True)

# Remove arquivo existente se houver
if os.path.exists(logo_path):
    os.remove(logo_path)
    print(f"Arquivo antigo removido: {logo_path}")

# Decodifica e salva
logo_bytes = base64.b64decode(logo_base64.strip())
with open(logo_path, 'wb') as f:
    f.write(logo_bytes)

print(f"✓ Logo da Caixa salvo em: {logo_path}")
print(f"✓ Tamanho: {len(logo_bytes)} bytes")
